# --- резервы ------------------------------------------------------------

def reserved(self, warehouse: str, sku: str) -> int:
    """Сумма активных (не истёкших) резервов позиции."""
    self._require_sku(sku)
    return self._reserved(warehouse, sku, self._clock.now())

def available(self, warehouse: str, sku: str) -> int:
    """Физический остаток за вычетом активных резервов, не меньше нуля."""
    self._require_sku(sku)
    return self._available(warehouse, sku, self._clock.now())

def reserve(
    self, order_id: str, lines: Iterable[object], ttl: timedelta | None = None
) -> Reservation:
    """Резервирует товар под заказ сразу по всем строкам."""
    now = self._clock.now()
    _validate_code(order_id, "order_id")
    ttl = validate_ttl(DEFAULT_RESERVATION_TTL if ttl is None else ttl)
    norm = normalize_lines(lines)
    for line in norm:
        self._check_position(line.warehouse, line.sku)
        _validate_qty(line.qty)
    existing = self._store.get_reservation(order_id)
    if existing is not None and effective_status(existing, now) in (
        ReservationStatus.ACTIVE,
        ReservationStatus.CONFIRMED,
    ):
        raise DuplicateReservationError(order_id)
    totals = _totals(norm)
    for line in norm:
        requested = totals[(line.warehouse, line.sku)]
        free = self._available(line.warehouse, line.sku, now)
        if requested > free:
            raise InsufficientStockError(line.warehouse, line.sku, requested, free)
    record = ReservationRecord(order_id, norm, now, now + ttl)
    self._store.put_reservation(record)
    expires = format_timestamp(record.expires_at)
    for line in norm:
        self._log.append(
            now, "RESERVE", order=order_id, wh=line.warehouse, sku=line.sku,
            qty=line.qty, expires=expires,
        )
    logger.info("reserved order %s (%d lines)", order_id, len(norm))
    return snapshot(record, now)

def confirm(self, order_id: str) -> Reservation:
    """Превращает активный резерв в отгрузку."""
    now = self._clock.now()
    record = self._find_reservation(order_id)
    self._require_active(record, now)
    totals = _totals(record.lines)
    for line in record.lines:
        requested = totals[(line.warehouse, line.sku)]
        physical = self._store.get_qty(line.warehouse, line.sku)
        if requested > physical:
            raise InsufficientStockError(line.warehouse, line.sku, requested, physical)
    for line in record.lines:
        self._write_issue(line.warehouse, line.sku, line.qty, order_id, now)
    record.status = ReservationStatus.CONFIRMED
    self._log.append(now, "RESERVE_CONFIRM", order=order_id)
    logger.info("confirmed order %s", order_id)
    return snapshot(record, now)

def cancel(self, order_id: str) -> Reservation:
    """Освобождает активный резерв; повторная отмена ничего не меняет."""
    now = self._clock.now()
    record = self._find_reservation(order_id)
    status = effective_status(record, now)
    if status is ReservationStatus.CONFIRMED:
        raise ReservationStateError(order_id, status.value)
    if status is ReservationStatus.ACTIVE:
        record.status = ReservationStatus.CANCELLED
        self._log.append(now, "RESERVE_CANCEL", order=order_id)
        logger.info("cancelled order %s", order_id)
    return snapshot(record, now)

def extend(self, order_id: str, ttl: timedelta) -> Reservation:
    """Переносит срок на ``now + ttl``, но никогда не сокращает его."""
    now = self._clock.now()
    _validate_code(order_id, "order_id")
    ttl = validate_ttl(ttl)
    record = self._find_reservation(order_id)
    self._require_active(record, now)
    new_expires = now + ttl
    if new_expires > record.expires_at:
        record.expires_at = new_expires
        self._log.append(
            now, "RESERVE_EXTEND", order=order_id, expires=format_timestamp(new_expires)
        )
        logger.info("extended order %s", order_id)
    return snapshot(record, now)

def get_reservation(self, order_id: str) -> Reservation:
    """Снимок резерва со статусом на текущий момент."""
    now = self._clock.now()
    return snapshot(self._find_reservation(order_id), now)

# --- служебное ----------------------------------------------------------

def _find_reservation(self, order_id: str) -> ReservationRecord:
    _validate_code(order_id, "order_id")
    record = self._store.get_reservation(order_id)
    if record is None:
        raise ReservationNotFoundError(order_id)
    return record

def _require_active(self, record: ReservationRecord, now: datetime) -> None:
    status = effective_status(record, now)
    if status is ReservationStatus.EXPIRED:
        raise ReservationExpiredError(record.order_id)
    if status is not ReservationStatus.ACTIVE:
        raise ReservationStateError(record.order_id, status.value)

def _reserved(self, warehouse: str, sku: str, now: datetime) -> int:
    return sum(
        line.qty
        for record in self._store.list_reservations()
        if effective_status(record, now) is ReservationStatus.ACTIVE
        for line in record.lines
        if line.warehouse == warehouse and line.sku == sku
    )

def _available(self, warehouse: str, sku: str, now: datetime) -> int:
    return max(0, self._store.get_qty(warehouse, sku) - self._reserved(warehouse, sku, now))

def _write_issue(
    self, warehouse: str, sku: str, qty: int, ref: str | None, now: datetime
) -> int:
    """Списывает физический остаток и пишет ``ISSUE`` без проверки резервов."""
    new_qty = self._store.get_qty(warehouse, sku) - qty
    self._store.set_qty(warehouse, sku, new_qty)
    self._log.append(now, "ISSUE", wh=warehouse, sku=sku, qty=qty, ref=ref)
    logger.info("issued %s x%d from %s", sku, qty, warehouse)
    return new_qty

